# Auto-generated by WLA experiments/rmbench adapter.
# This file is copied into an RMBench checkout by run_rmbench_eval.py.

import json
import os
import re
import sys
from pathlib import Path
from typing import Any, Optional

import numpy as np
import torch
from torchvision.transforms.functional import to_tensor


def _get_arg(args: dict[str, Any], key: str, default: Any = None) -> Any:
    value = args.get(key, default)
    return default if value is None else value


def _as_bool(value: Any, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "y", "on"}
    return bool(value)


def _as_optional_path(value: Any) -> Optional[str]:
    if value in {None, "", "None", "none", "null"}:
        return None
    return str(value)


def _resolve_wla_root(args: dict[str, Any]) -> Path:
    raw_root = os.environ.get("WLA_ROOT") or args.get("wla_root")
    if not raw_root:
        raise RuntimeError(
            "WLA_ROOT is not set. Run through experiments/rmbench/run_rmbench_eval.py "
            "so the adapter can import the WLA model code."
        )

    root = Path(raw_root).expanduser().resolve()
    if not (root / "models" / "wla.py").is_file():
        raise FileNotFoundError(f"Invalid WLA root: {root}")
    return root


def _resolve_file(path_value: Any, wla_root: Path, *, default: Optional[str] = None) -> Optional[str]:
    path = _as_optional_path(path_value if path_value is not None else default)
    if path is None:
        return None

    expanded = Path(path).expanduser()
    if expanded.is_absolute():
        return str(expanded)

    wla_candidate = wla_root / expanded
    if wla_candidate.exists():
        return str(wla_candidate)

    cwd_candidate = Path.cwd() / expanded
    if cwd_candidate.exists():
        return str(cwd_candidate)

    return str(wla_candidate)


def _resolve_model_id(model_id: str, wla_root: Path) -> str:
    expanded = Path(model_id).expanduser()
    if expanded.is_absolute():
        return str(expanded)

    wla_candidate = wla_root / expanded
    if wla_candidate.exists():
        return str(wla_candidate)

    cwd_candidate = Path.cwd() / expanded
    if cwd_candidate.exists():
        return str(cwd_candidate)

    return model_id


def _import_wla_modules(wla_root: Path):
    root = str(wla_root)
    if root not in sys.path:
        sys.path.insert(0, root)

    from models.wla import WLA
    from utils.transforms import _make_transform, normalize_and_pad, unnormalize_and_unpad

    return WLA, _make_transform, normalize_and_pad, unnormalize_and_unpad


def _to_list(value: Any) -> list[float]:
    return np.asarray(value, dtype=np.float32).reshape(-1).tolist()


def _required_arg(args: dict[str, Any], key: str) -> Any:
    value = _get_arg(args, key)
    if value in {None, "", "None", "none", "null"}:
        raise ValueError(f"{key} is required. Set it in run_rmbench_eval.sh or pass --{key}.")
    return value


def _validate_control_mode(control_mode: str) -> str:
    control_mode = control_mode.lower()
    if control_mode not in {"eef", "joint"}:
        raise ValueError(f"Unsupported control_mode: {control_mode}. Expected 'eef' or 'joint'.")
    return control_mode


def _normalize_quaternion(quaternion: torch.Tensor) -> torch.Tensor:
    norm = torch.linalg.norm(quaternion, dim=1, keepdim=True).clamp_min(1e-6)
    return quaternion / norm


SUBTASK_ENDINGS = (".", "!", "?", "。", "！", "？")


def _safe_int(value: Any, default: int = -1) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _normalize_subtask_text(text: Any) -> str:
    text = str(text).strip()
    if not text:
        return ""
    return text if text.endswith(SUBTASK_ENDINGS) else f"{text}."


def _split_subtask_text(text: Any) -> list[str]:
    pieces = re.findall(r"[^.!?。！？]+[.!?。！？]?", str(text))
    normalized = [_normalize_subtask_text(piece) for piece in pieces]
    return [piece for piece in normalized if piece]


def _force_inference_steps(model: Any, num_inference_timesteps: int):
    model.config.num_inference_timesteps = num_inference_timesteps
    if hasattr(model.model, "config"):
        model.model.config.num_inference_timesteps = num_inference_timesteps

    for head_name in ("action_expert", "policy_head"):
        if not hasattr(model.model, head_name):
            continue
        action_head = getattr(model.model, head_name)
        action_head.num_inference_timesteps = num_inference_timesteps
        if hasattr(action_head, "config"):
            action_head.config.num_inference_timesteps = num_inference_timesteps


class WLARMBenchPolicy:
    def __init__(
        self,
        *,
        wla_root: Path,
        model_id: str,
        checkpoints_dir: Optional[str],
        norm_file_path: str,
        unnorm_key: str,
        control_mode: str,
        max_state_dim: int,
        original_action_dim: int,
        target_image_size: int = 512,
        vae_downsample_f: int = 32,
        primary_image_size: int = 256,
        auxiliary_image_size: int = 256,
        action_chunk_size: Optional[int] = None,
        strip_world_model: bool = True,
        dtype: str = "bfloat16",
    ):
        WLA, make_transform, normalize_and_pad, unnormalize_and_unpad = _import_wla_modules(wla_root)
        self.make_transform = make_transform
        self.normalize_and_pad = normalize_and_pad
        self.unnormalize_and_unpad = unnormalize_and_unpad

        self.control_mode = control_mode
        self.wla_root = wla_root
        self.max_state_dim = max_state_dim
        self.original_action_dim = original_action_dim
        self.primary_image_size = primary_image_size
        self.auxiliary_image_size = auxiliary_image_size
        self.history_obs_step = 32
        self.action_chunk_size = action_chunk_size
        self.history_observation = None
        self.begin_observation = None
        self.subtask_history_items = []
        self.subtask_history_text = ""
        self.subtask_call_index = 0
        self.subtask_log_path = None
        self.language_mode = False
        self.use_begin_frame_context = False

        with open(norm_file_path, "r", encoding="utf-8") as f:
            norm_stats = json.load(f)
        if unnorm_key not in norm_stats:
            available = ", ".join(sorted(norm_stats.keys()))
            raise KeyError(f"Normalization key '{unnorm_key}' not found. Available keys: {available}")
        self.norm_stats = norm_stats[unnorm_key]

        input_size = target_image_size // vae_downsample_f
        print(f"Loading WLA model from: {model_id}")
        self.model = WLA.from_pretrained(model_id, input_size=input_size)

        if checkpoints_dir:
            checkpoint_path = Path(checkpoints_dir).expanduser()
            if checkpoint_path.is_dir():
                checkpoint_path = checkpoint_path / "model.pt"
            print(f"Loading WLA checkpoint from: {checkpoint_path}")
            state_dict = torch.load(str(checkpoint_path), map_location="cpu")
            state_dict = {key.replace("module.", ""): value for key, value in state_dict.items()}
            self.model.load_state_dict(state_dict)
            del state_dict

        config_history_obs_step = getattr(self.model.config, "history_obs_step", None)
        if config_history_obs_step is not None:
            self.history_obs_step = int(config_history_obs_step)

        forced_num_inference_timesteps = 32
        _force_inference_steps(self.model, forced_num_inference_timesteps)
        print(f"Force num_inference_timesteps={forced_num_inference_timesteps}")

        if strip_world_model:
            self._strip_unused_modules()

        self.language_mode = "language" in str(getattr(self.model.config, "training_mode", ""))
        self.use_begin_frame_context = _as_bool(getattr(self.model.config, "use_begin_frame_context", False))
        print(f"use_begin_frame_context={self.use_begin_frame_context}")
        print(f"language_mode={self.language_mode}")
        if self.language_mode:
            print("WLA RMBench adapter: language-context inference is enabled.")

        torch_dtype = getattr(torch, dtype)
        device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        self.model = self.model.to(device=device, dtype=torch_dtype)
        self.model.eval()

    @classmethod
    def from_usr_args(cls, usr_args: dict[str, Any]):
        wla_root = _resolve_wla_root(usr_args)
        control_mode = _validate_control_mode(str(_required_arg(usr_args, "control_mode")))

        model_id = _get_arg(usr_args, "model_id")
        if not model_id:
            raise ValueError("model_id is required. Pass it via run_rmbench_eval.sh arg 6 or --model_id.")

        checkpoints_dir = _resolve_file(_get_arg(usr_args, "checkpoints_dir"), wla_root)
        norm_file_path = _resolve_file(
            os.environ.get("MANTIS_NORM_STATS_PATH") or _get_arg(usr_args, "norm_file_path"),
            wla_root,
            default="configs/norm_stats.json",
        )
        unnorm_key = os.environ.get("MANTIS_NORM_KEY") or _required_arg(usr_args, "unnorm_key")

        action_chunk_size = _get_arg(usr_args, "action_chunk_size")
        if action_chunk_size in {None, "", "None", "none", "null"}:
            action_chunk_size = None
        else:
            action_chunk_size = int(action_chunk_size)

        return cls(
            wla_root=wla_root,
            model_id=_resolve_model_id(str(model_id), wla_root),
            checkpoints_dir=checkpoints_dir,
            norm_file_path=norm_file_path,
            unnorm_key=str(unnorm_key),
            control_mode=control_mode,
            target_image_size=int(_get_arg(usr_args, "target_image_size", 512)),
            vae_downsample_f=int(_get_arg(usr_args, "vae_downsample_f", 32)),
            max_state_dim=int(_required_arg(usr_args, "max_state_dim")),
            original_action_dim=int(_required_arg(usr_args, "original_action_dim")),
            primary_image_size=int(_get_arg(usr_args, "primary_image_size", 256)),
            auxiliary_image_size=int(_get_arg(usr_args, "auxiliary_image_size", 256)),
            action_chunk_size=action_chunk_size,
            strip_world_model=_as_bool(_get_arg(usr_args, "strip_world_model"), True),
            dtype=str(_get_arg(usr_args, "dtype", "bfloat16")),
        )

    def reset(self):
        self.history_observation = None
        self.begin_observation = None
        self.subtask_history_items = []
        self.subtask_history_text = ""
        self.subtask_call_index = 0

    def _strip_unused_modules(self):
        for module_name in ("world_expert", "connector"):
            if hasattr(self.model.model, module_name):
                delattr(self.model.model, module_name)
        if hasattr(self.model, "vae"):
            delattr(self.model, "vae")

    def _encode_obs(self, observation: dict[str, Any]):
        obs = observation["observation"]
        if self.begin_observation is None:
            self.begin_observation = observation

        head_camera_tensor = to_tensor(obs["head_camera"]["rgb"])
        left_camera_tensor = to_tensor(obs["left_camera"]["rgb"])
        right_camera_tensor = to_tensor(obs["right_camera"]["rgb"])

        history_head_camera_tensor = None
        if self.history_observation is not None:
            history_head_camera_tensor = to_tensor(
                self.history_observation["observation"]["head_camera"]["rgb"]
            )

        primary_image_transform = self.make_transform(self.primary_image_size)
        auxiliary_image_transform = self.make_transform(self.auxiliary_image_size)
        current_images = [
            primary_image_transform(head_camera_tensor),
            auxiliary_image_transform(left_camera_tensor),
            auxiliary_image_transform(right_camera_tensor),
        ]

        if self.use_begin_frame_context:
            begin_head_camera_tensor = to_tensor(
                self.begin_observation["observation"]["head_camera"]["rgb"]
            )
            image_context = [primary_image_transform(begin_head_camera_tensor)]
            if self.history_observation is not None:
                image_context.append(auxiliary_image_transform(history_head_camera_tensor))
            image_context.extend(current_images)
        else:
            image_context = list(current_images)
            if self.history_observation is not None:
                image_context.insert(0, auxiliary_image_transform(history_head_camera_tensor))

        input_images = [image_context]

        if self.control_mode == "eef":
            endpose = observation["endpose"]
            if "left_endpose" in endpose:
                state = (
                    _to_list(endpose["left_endpose"])
                    + _to_list(endpose["left_gripper"])
                    + _to_list(endpose["right_endpose"])
                    + _to_list(endpose["right_gripper"])
                )
            else:
                state = _to_list(endpose["endpose"]) + _to_list(endpose["gripper"])
        else:
            state = _to_list(observation["joint_action"]["vector"])

        states = torch.tensor(state, dtype=torch.float32)
        states, _ = self.normalize_and_pad(
            states,
            self.norm_stats["observation.state"],
            self.max_state_dim,
        )

        return input_images, states.unsqueeze(0)

    def _append_subtask_history(self, subtask_text: Any):
        for text in _split_subtask_text(subtask_text):
            if not self.subtask_history_items or self.subtask_history_items[-1] != text:
                self.subtask_history_items.append(text)
        self.subtask_history_text = " ".join(self.subtask_history_items)

    def _resolve_subtask_log_path(self, TASK_ENV) -> Optional[str]:
        eval_video_path = getattr(TASK_ENV, "eval_video_path", None)
        if eval_video_path is None:
            return None
        log_path = os.path.join(str(eval_video_path), "subtasks.jsonl")

        if self.subtask_log_path != log_path:
            print(f"Subtask log: {log_path}")
            self.subtask_log_path = log_path
        return log_path

    def _record_subtask(self, TASK_ENV, instruction: str, history_subtask_text: str, subtask_text: Any):
        if subtask_text is None:
            return

        log_path = self._resolve_subtask_log_path(TASK_ENV)
        if log_path is None:
            return

        log_dir = os.path.dirname(log_path)
        if log_dir:
            os.makedirs(log_dir, exist_ok=True)

        record = {
            "episode": _safe_int(getattr(TASK_ENV, "test_num", None)),
            "call_index": self.subtask_call_index,
            "take_action_cnt": _safe_int(getattr(TASK_ENV, "take_action_cnt", None)),
            "instruction": instruction,
            "history_subtask_text": history_subtask_text,
            "subtask_text": subtask_text,
        }
        with open(log_path, "a", encoding="utf-8") as f:
            f.write(json.dumps(record, ensure_ascii=False) + "\n")

        self.subtask_call_index += 1

    def _postprocess_actions(self, actions: Any) -> torch.Tensor:
        actions = torch.as_tensor(actions)
        if actions.ndim == 1:
            actions = actions.unsqueeze(0)
        actions = self.unnormalize_and_unpad(
            actions,
            self.norm_stats["action"],
            self.original_action_dim,
            add_eps=False,
        )

        if self.control_mode == "eef":
            if actions.shape[-1] >= 16:
                left_quat = _normalize_quaternion(actions[:, 3:7])
                right_quat = _normalize_quaternion(actions[:, 11:15])
                actions = torch.cat(
                    [
                        actions[:, :3],
                        left_quat,
                        actions[:, 7:11],
                        right_quat,
                        actions[:, 15:16],
                    ],
                    dim=1,
                )
            elif actions.shape[-1] >= 8:
                left_quat = _normalize_quaternion(actions[:, 3:7])
                actions = torch.cat([actions[:, :3], left_quat, actions[:, 7:8]], dim=1)
            else:
                raise ValueError(f"EEF action must have 8 or 16 dims, got {actions.shape[-1]}.")

        if self.action_chunk_size is not None:
            actions = actions[: self.action_chunk_size]
        return actions

    def _predict_actions(self, TASK_ENV, observation: dict[str, Any], instruction: str) -> tuple[torch.Tensor, Optional[str]]:
        input_images, states = self._encode_obs(observation)

        model_dtype = next(self.model.model.action_expert.parameters()).dtype
        model_device = next(self.model.model.action_expert.parameters()).device
        states = states.to(dtype=model_dtype, device=model_device)

        history_subtask_text = self.subtask_history_text
        subtask_text = None
        if self.language_mode:
            with torch.no_grad():
                subtask_text = self.model.generate_subtask(
                    caption=instruction,
                    input_images=input_images,
                    history_subtask_text=history_subtask_text,
                )
            self._record_subtask(TASK_ENV, instruction, history_subtask_text, subtask_text)
            if subtask_text:
                print(f"WLA generated subtask: {subtask_text}")

        with torch.no_grad():
            actions = self.model.sample_actions(
                caption=instruction,
                input_images=input_images,
                num_images_per_prompt=1,
                states=states,
                history_subtask_text=history_subtask_text,
                subtask_text=subtask_text,
            )
        return self._postprocess_actions(actions), subtask_text

    def eval_step(self, TASK_ENV, observation: dict[str, Any]):
        instruction = TASK_ENV.get_instruction()
        actions, subtask_text = self._predict_actions(TASK_ENV, observation, instruction)
        target_history_index = len(actions) - self.history_obs_step - 1
        next_history_observation = observation if target_history_index < 0 else self.history_observation

        for index, action in enumerate(actions):
            action = action.detach().cpu().numpy()
            if self.control_mode == "eef":
                TASK_ENV.take_action(action, action_type="ee")
            else:
                TASK_ENV.take_action(action)
            observation = TASK_ENV.get_obs()
            if index == target_history_index:
                next_history_observation = observation

        self.history_observation = next_history_observation
        if subtask_text:
            self._append_subtask_history(subtask_text)

        return next_history_observation
